-- Mauritania fourth preparatory year (mapped grade 10): 43 original
-- supplementary exercises across existing official-import title stubs.
-- Independent educational prose; all ministry/source matching is pending.
DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"9b9a589d-6032-4966-a6f5-1c0e0efa40b3","n":1,"title":"الخطاب الصحفي","passage":"يختار الخطاب الصحفي خبرًا ذا أهمية لجمهور معلوم، ويقدم الوقائع بلغة قابلة للتحقق مع التمييز بين التقرير والرأي. في نموذج أصلي يعلن نادي المدرسة عن معرض للقراءة ويذكر مكانه وتاريخه وجهة التنظيم؛ لا يخترع أرقام الحضور.","question":"ما المعلومة الأساسية التي تزيد قابلية الخبر للتحقق؟","correct":"الزمان والمكان والمصدر","wrong":["مديح بلا واقعة","عنوان صاخب دون متن","مجهولية جهة النشر"],"practice":"اكتب خبرًا تدريبيًا عن فعالية متخيلة مع فصل الواقعة عن رأيك وتحديد المصدر المعلن.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"9b9a589d-6032-4966-a6f5-1c0e0efa40b3","n":2,"title":"كيف نحمي مقدساتنا","passage":"يتناول العنوان موضوعًا ذا قيم دينية وثقافية، ولا يجوز نسبة جمل إلى نص ديني أو مؤلف من دون مرجع. في موقف أصلي يحافظ زوار على نظافة مكان عبادة ويحترمون قواعده وحق الآخرين في الهدوء، وهو مثال مدني للتعامل باحترام لا اقتباس من المادة المدرسية.","question":"ما السلوك السلمي في المثال الذي يحترم المكان؟","correct":"المحافظة على النظافة وحقوق الزوار","wrong":["الإضرار بالمرفق","إزعاج الآخرين","نشر اتهامات"],"practice":"حلل النص المقرر من مصدر موثق وناقش دور الحوار والسلوك المسؤول في حماية التراث.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"9b9a589d-6032-4966-a6f5-1c0e0efa40b3","n":3,"title":"اسم الآلة","passage":"يدل اسم الآلة على أداة يؤدى بها الفعل، مثل «مفتاح» و«منشار»، وتتنوع أوزانه القياسية والسماعية. نميز الاسم عن الفعل والفاعل؛ فـ«مفتاح» ليس «فاتحًا» بوصفه اسم فاعل. تعتمد دقة التحليل على الجذر والاستعمال.","question":"أي كلمة تدل على أداة فتح؟","correct":"مفتاح","wrong":["فاتح","مفتوح","فتح"],"practice":"صنف أسماء ست أدوات وفق صيغها، ثم استعمل ثلاثًا منها في جمل صحيحة.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"9b9a589d-6032-4966-a6f5-1c0e0efa40b3","n":4,"title":"الخطاب السياسي","passage":"يتضمن الخطاب السياسي آراءً ووعودًا ومواقف وقضايا عامة، ويحتاج القارئ إلى تفريق الادعاء عن الدليل والتحقق من الأرقام والسياق والمخاطب. في مثال مستقل يناقش مجلس طلابي آلية توزيع قاعات النشاط، مع آراء متنوعة وقاعدة معلنة للقرار.","question":"ما الممارسة النقدية الأفضل لقراءة خطاب عن قرار عام؟","correct":"مراجعة الحجة والمصدر والآراء البديلة","wrong":["اعتبار الشعار دليلًا","إلغاء الاختلاف","نسبة اقتباسات بلا تحقق"],"practice":"اختر مقطعًا عامًا مأذونًا من خطاب موثق، واستخرج دعوى ودليلًا وسؤالًا للتحقق دون دعوة حزبية.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"9b9a589d-6032-4966-a6f5-1c0e0efa40b3","n":5,"title":"أيها الأبناء","passage":"لا يُستنتج محتوى خطاب «أيها الأبناء» أو صاحبه من العنوان، ولا تُنسب إليه وصية مختلقة. في مثال أصلي يوجه معلم أبناءه الطلاب إلى توثيق المصادر قبل المشاركة في النقاش، فيفهم الطالب دور النداء والأمر وأثر النبرة.","question":"ما الأسلوب في بداية «أيها الأبناء»؟","correct":"نداء موجه إلى المخاطبين","wrong":["أداة نفي","مفعول مطلق","قسم"],"practice":"ارجع إلى الخطاب المدرسي الصحيح واستخرج أسلوب نداء وحجة مع شرح أثرهما.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"9b9a589d-6032-4966-a6f5-1c0e0efa40b3","n":6,"title":"اسم الزمان واسم المكان","passage":"يدل اسم الزمان أو المكان على وقت وقوع الفعل أو موضعه وفق السياق، مثل «مَطلع» في استعمال يحدد وقت الطلوع أو مكانه. تتشابه الأبنية أحيانًا ولا يحسم الوزن المعنى وحده؛ يجب قراءة التركيب ومجاله.","question":"ما الذي يرجح معنى الزمان أو المكان لاسم مشتق؟","correct":"سياق الجملة والمرجع","wrong":["عدد الحروف وحده","ترتيب السطر","علامة الاستفهام"],"practice":"صغ أربعة تراكيب لأسماء زمان ومكان واشرح قرينة التحديد في كل سياق.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"9b9a589d-6032-4966-a6f5-1c0e0efa40b3","n":7,"title":"الجملة الابتدائية","passage":"تأتي الجملة الابتدائية في بدء الكلام أو استئناف مقطع غير متعلق إعرابيًا بما قبله في مواضعها المعروفة، مثل «العلمُ نافعٌ» عند افتتاح الكلام. لا يعني ذلك أن كل جملة تسبقها نقطة مستقلة بالضرورة؛ يُراعى الربط النحوي والمعنى.","question":"ما محل الجملة الابتدائية من الإعراب غالبًا؟","correct":"لا محل لها من الإعراب","wrong":["في محل نصب مفعول به دائمًا","في محل جر دائمًا","بدل منصوب دائمًا"],"practice":"حدد جملًا ابتدائية واستئنافية من نص قصير مع تعليل عدم المحل أو وجوده.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"9b9a589d-6032-4966-a6f5-1c0e0efa40b3","n":8,"title":"مهارة الدفاع عن وجهة نظر","passage":"يعرض الكاتب أطروحة واضحة وسببين وحجة مضادة ثم ردًا منصفًا، دون مهاجمة الأشخاص أو تقديم ادعاء لا يمكن اختباره. مثال أصلي يفضل طالب وقتًا ثابتًا للمراجعة لأنه يساعد على متابعة تقدمه، ويعترف باختلاف ظروف زملائه.","question":"ما العنصر الذي يجعل الدفاع عن رأي أكثر إقناعًا؟","correct":"الاعتراف بالاعتراض والرد بدليل","wrong":["إسكات المعارض","تكرار الرأي فقط","إخفاء المقدمات"],"practice":"قدم مرافعة شفوية قصيرة حول قرار مدرسي مع شاهد واعتراض ورد متزن.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"34cda86c-77c9-47ba-b523-ca342533de24","n":1,"title":"الرياضيات عند العرب","passage":"لا يصح نسبة اختراع أو مسألة رياضية إلى عالم تاريخي دون نص محقق وتاريخ وسياق. تُدرس أساليب التصنيف وحل المسائل في المصادر المعتمدة، مع مقارنة منهج قديم بوصف رياضي معاصر. مثال مستقل يُظهر طالبًا يرتب خطوات حل معادلة لتسهيل مراجعتها.","question":"ما أفضل دليل لنسبة عمل رياضي لعالم تاريخي؟","correct":"كتاب أو مخطوط محقق مع مصدر","wrong":["اسم مشهور وحده","قصة مجهولة","تخمين تاريخ"],"practice":"اختر مسألة تاريخية موثقة وفسر طريقتها، ثم قارن الرموز بالمستعمل اليوم.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"34cda86c-77c9-47ba-b523-ca342533de24","n":2,"title":"الجملة الواقعة مضافا إليه ما قبلها","passage":"تُبحث الجملة المضافة إليها في ظروف وأسماء معينة، مثل «جئتُ حينَ بدأَ الاجتماعُ»؛ جملة «بدأ الاجتماع» في محل جر بالإضافة إلى الظرف «حين». يتحدد الإعراب وفق نوع الاسم السابق والبناء الكلي.","question":"ما موقع جملة «بدأ الاجتماع» بعد «حين» في المثال؟","correct":"في محل جر بالإضافة","wrong":["فاعل مرفوع","نعت منصوب","جواب قسم"],"practice":"حلل ثلاثة تراكيب بظروف تضاف إلى جمل، مع ذكر الموقع والرابط.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"34cda86c-77c9-47ba-b523-ca342533de24","n":3,"title":"أسباب تأليف كتاب الجبر والمقابلة","passage":"يتطلب شرح سبب تأليف «كتاب الجبر والمقابلة» الرجوع إلى مقدمة النص المحقق وسياقه التاريخي، وعدم تخمين نية المؤلف أو اختلاق اقتباس. في تمرين مستقل يذكر متعلم أن تنظيم مسائل الحساب يساعد على تعليم الحلول، لكنه لا ينسب ذلك بوصفه نص المقدمة.","question":"ما الطريقة الصحيحة لإثبات سبب تأليف كتاب تاريخي؟","correct":"الرجوع إلى مقدمته المحققة ومراجع السياق","wrong":["اختلاق خطاب للمؤلف","الاستدلال بعنوان فقط","نسبته إلى عالم آخر"],"practice":"بعد قراءة المقدمة الموثقة، استخرج سببًا بنص قصير صحيح المصدر وفسر عبارته.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"34cda86c-77c9-47ba-b523-ca342533de24","n":4,"title":"الجملة الاعتراضية","passage":"تقع الجملة الاعتراضية بين أجزاء الكلام لتؤدي معنى كالدعاء أو التوضيح، من غير أن تكون ركنًا إعرابيًا لازمًا في التركيب الأصلي. في «المعلمُ — جزاه الله خيرًا — قدّم الدرسَ» الجملة المعترضة لا تغير العلاقة بين المبتدأ وخبره.","question":"ما وظيفة «جزاه الله خيرًا» في المثال؟","correct":"جملة اعتراضية","wrong":["فاعل الجملة الأصلية","مفعول به للمعلم","نعت لازم"],"practice":"ضع جملتين اعتراضيتين في سياقين مناسبين وبيّن المعنى قبل الحذف وبعده.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"34cda86c-77c9-47ba-b523-ca342533de24","n":5,"title":"مقدمة كتاب مفاتيح العلوم","passage":"تحتاج دراسة مقدمة «مفاتيح العلوم» إلى نسخة نصية محققة للتحقق من قصد المؤلف وترتيب العلوم وتعريفاته؛ لا يصح تأليف مقدمة ونسبتها إليه. تدريب مستقل يشرح الفرق بين فهرس مصطلحات وتقديم منهجي للكتاب.","question":"ما الذي يساعد في تحديد غرض مقدمة كتاب تراثي؟","correct":"قراءة نص المقدمة المعتمد وتحليل عباراته","wrong":["الاعتماد على اسم الكتاب","تخمين تاريخ الطبعة","تأليف تمهيد جديد باسمه"],"practice":"استخرج تعريفًا صحيحًا من مقدمة محققة ثم بين وظيفته في تنظيم المعرفة.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"34cda86c-77c9-47ba-b523-ca342533de24","n":6,"title":"مهارة توسيع فكرة","passage":"يتحول العنوان إلى فقرة عبر تفسير الفكرة وذكر مثال ودليل والربط بين الجمل ثم خلاصة، دون حشو أو نسخ. مثال مستقل: «تدقيق المصادر يعزز الثقة» يمكن توسيعه بشرح كيف يُراجع الاسم والتاريخ والأدلة في تقرير مدرسي.","question":"ما الإضافة التي تجعل التوسيع مفيدًا؟","correct":"تفصيل وتعليل وشاهد متصل بالفكرة","wrong":["تكرار العنوان خمس مرات","إدخال موضوع لا علاقة له","إلغاء الخاتمة"],"practice":"وسّع فكرة من سطر واحد إلى ستة أسطر منظمة مع مثال وحدود.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"307ca786-7508-42b1-850a-0a50787af88b","n":1,"title":"التيارات الأدبية والفنية في العصر العباسي","passage":"شهد النتاج العباسي تنوعًا في الموضوع والصورة والأسلوب بحسب المراحل والشعراء والبيئات؛ يجب تحليل نصوص محققة قبل تسمية تيار ووصف ملامحه. لا يصح اعتبار كل نص عباسي ممثلًا لفترة واحدة أو رأي واحد.","question":"ما الذي يضبط تصنيف تيار أدبي تاريخي؟","correct":"نصوص موثقة ومقارنة سياقاتها","wrong":["اسم العصر وحده","رواية مجهولة","تشابه القافية فقط"],"practice":"قارن نصين عباسيين محققين من تيارين أو غرضين، مع دليل على الاختلاف.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"307ca786-7508-42b1-850a-0a50787af88b","n":2,"title":"تيار المجون في العصر العباسي","passage":"يفصل الباحث بين وصف اللهو في شعر عباسي وبين موقف الشاعر الشخصي وأحكام الاعتقاد التاريخية؛ فقد تتضمن القصيدة سخرية أو مبالغة. لا تُثبت حياة شخصية من بيت متخيل أو خبر غير مسند، وتحليل النص أدبي لا دعوة إلى سلوك ضار.","question":"ما الذي يمنع تحويل الصورة الشعرية إلى حكم سيرة مؤكدة؟","correct":"التثبت من المصدر وسياق المتكلم والمجاز","wrong":["الاعتماد على بيت مجهول","اختراع رواية","تعميم النص على المجتمع"],"practice":"اختر نصًا صحيح النسبة وحلل النبرة والغرض مع الفصل بين الشعر والتاريخ.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"307ca786-7508-42b1-850a-0a50787af88b","n":3,"title":"اسم المرة واسم الهيئة","passage":"اسم المرة يدل على وقوع الحدث مرة واحدة، مثل «جَلْسة» من «جلس»، وقد يأتي اسم الهيئة على «فِعْلة» في قياس معروف مثل «جِلسة» للدلالة على هيئة الجلوس. لا يحسم الرسم وحده المعنى إذا لم تضبط الحركة ويُعرف السياق.","question":"ما دلالة «جَلْسة» بفتح الجيم في المثال؟","correct":"وقوع الجلوس مرة واحدة","wrong":["اسم فاعل","حرف استفهام","فاعل نحوي"],"practice":"اكتب ثلاثة أمثلة تميز اسم المرة والهيئة بالحركة والمعنى في سياقات مضبوطة.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"307ca786-7508-42b1-850a-0a50787af88b","n":4,"title":"تيار الزهد في العصر العباسي","passage":"قد يتناول شعر الزهد قصر الحياة ومحاسبة النفس والابتعاد عن التفاخر بالمظاهر؛ لا ينبغي اقتباس أبيات غير محققة أو تحويل كل حزن إلى زهد. مثال مستقل يفضل شخص مساعدة محتاج إلى إنفاق موارد على مظهر غير ضروري.","question":"ما السلوك الذي يمثل تقليل التعلق بالمظهر في المثال؟","correct":"تقديم المساعدة على المباهاة","wrong":["شراء أشياء للتفاخر","إخفاء الحاجة","تجاهل الآخر"],"practice":"استخرج من نص زهد موثق معنى أخلاقيًا وصورة فنية دون نسبة أبيات مختلقة.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"307ca786-7508-42b1-850a-0a50787af88b","n":5,"title":"أركان التشبيه","passage":"في «العلمُ كالنورِ في الهداية» العلم مشبه والنور مشبه به والكاف أداة، والهداية وجه الشبه في هذا التمثيل. قد تحذف الأداة أو الوجه فتصنف الصورة على وجه مختلف؛ لا يكفي ذكر كلمة «نور» وحدها.","question":"ما المشبه به في «العلم كالنور»؟","correct":"النور","wrong":["العلم","الكاف","في"],"practice":"أنشئ ثلاثة تشبيهات وحدد أركان كل واحد ووجه ملاءمتها.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"307ca786-7508-42b1-850a-0a50787af88b","n":6,"title":"تيار البيان في العصر العباسي","passage":"تقوم دراسة مظاهر البيان على تحليل الصور والحجج وصناعة النثر والشعر في نصوص صحيحة النسبة، ولا يمكن الحكم على تيار كامل بعنوان درس فقط. تدريب مستقل يقارن أسلوبين يعرضان الفكرة نفسها: تعبير مباشر وتعبير استعاري.","question":"ما الذي يكشف تنوع البيان في النص؟","correct":"مقارنة الصياغة والصورة ووظيفتهما","wrong":["عدد الصفحات","اسم الشاعر دون نص","إغفال المخاطب"],"practice":"حلل مثالين موثقين مختلفي الأسلوب، وبيّن أثر الصورة في الفكرة.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"307ca786-7508-42b1-850a-0a50787af88b","n":7,"title":"البحر الكامل","passage":"تقوم الصيغة التامة الأصلية للبحر الكامل على «متفاعلن متفاعلن متفاعلن» في كل شطر مع زحافات وعلل معروفة. التقطيع يعتمد الأصوات المنطوقة لا الحروف المكتوبة فقط، ويحتاج بيتًا صحيح النسبة.","question":"ما تفعيلة البحر الكامل الأساسية؟","correct":"متفاعلن","wrong":["فاعلاتن","فعولن","مستفعلن وحدها"],"practice":"اقطع بيتًا موثقًا على الكامل مع تحديد التفعيلات والتغييرات إن وجدت.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"307ca786-7508-42b1-850a-0a50787af88b","n":8,"title":"مهارة المقارنة والاستنتاج","passage":"لا تقوم المقارنة المتزنة على اختيار رأي مسبق؛ بل تحدد معيارًا مشتركًا وتجمع الملاحظات لكل نص ثم تستنتج قدر التشابه والاختلاف. مثال مستقل يقارن متعلم فقرتين في وضوح الفكرة ونوعية الاستشهاد.","question":"ما الذي يلزم قبل الحكم على نصين بالمفاضلة؟","correct":"معيار معلن وشواهد لكليهما","wrong":["إخفاء المعيار","الاعتماد على طول النص","تخمين نية الكاتب"],"practice":"اكتب مقارنة في جدول بين فقرتين مأذونتين مع ثلاثة معايير واستنتاج معلل.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"0ceee54c-088c-4480-8bbc-c8353244ff17","n":1,"title":"الديموقراطية","passage":"يدرس النص مفهوم المشاركة في القرار والتمثيل والمساءلة واختلاف النماذج السياسية بحسب الدساتير والسياقات، لا بوصفه شعارًا يثبت نظامًا بعينه. في مثال مدرسي مستقل تختار لجنة نشاط خطة عمل بعد استماع لآراء الأعضاء وفق قواعد معلنة.","question":"ما الذي يجعل قرار اللجنة قابلًا للمساءلة في المثال؟","correct":"وجود قواعد معلنة وإمكانية مراجعة القرار","wrong":["إخفاء التصويت","منع الأسئلة","حذف الأسباب"],"practice":"حلل فقرة تعليمية موثقة عن آلية مشاركة عامة، وقارنها بنموذج مدرسي مستقل بإنصاف.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"0ceee54c-088c-4480-8bbc-c8353244ff17","n":2,"title":"المصدر الصناعي","passage":"يتكون المصدر الصناعي بإضافة ياء النسب المشددة وتاء مربوطة في صيغ مثل «إنسانية» من «إنسان»، فيدل على معنى مجرد أو خاصية. لا نجزم بأن كل اسم منتهٍ بتاء مربوطة مصدر صناعي؛ تُراجع البنية.","question":"أي كلمة مثال لمصدر صناعي؟","correct":"إنسانية","wrong":["إنسان","أُناس","إنسانان"],"practice":"صغ أربعة مصادر صناعية واشرح أصل كل منها ودلالته في جملة.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"0ceee54c-088c-4480-8bbc-c8353244ff17","n":3,"title":"تلوث طبقة الأوزون","passage":"يجب التمييز علميًا بين استنزاف الأوزون في طبقة الستراتوسفير الذي يؤثر في الحماية من الأشعة فوق البنفسجية، وبين الأوزون قرب سطح الأرض الذي يُعد ملوثًا للهواء في ظروف معينة. يتطلب التفسير مصادر بيئية علمية موثوقة، لا عنوانًا عامًا فقط.","question":"ما الضرر المرتبط باستنزاف أوزون الستراتوسفير؟","correct":"تراجع الحماية من بعض الأشعة فوق البنفسجية","wrong":["انعدام جاذبية الأرض","اختفاء الماء مباشرة","توقف دوران الأرض"],"practice":"أعد فقرة بمصدرين علميين تميز بين أوزون الطبقات العليا والسطح والتأثيرات المختلفة.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"0ceee54c-088c-4480-8bbc-c8353244ff17","n":4,"title":"النحت والاقتراض","passage":"النحت تكوين لفظ من أجزاء كلمات أو تعبيرات بحسب الاستعمال، أما الاقتراض اللغوي فانتقال لفظ من لغة أخرى مع احتمال التكييف الصوتي أو الكتابي. لا يُحسم أصل كلمة حديثة دون معجم تاريخي أو مرجع متخصص.","question":"ما الذي يميز الاقتراض عن النحت؟","correct":"انتقال لفظ بين لغتين مقابل تركيب أجزاء ألفاظ","wrong":["معناهما مترادفان دائمًا","النحت نوع من الإعراب","الاقتراض حرف جر"],"practice":"وثق مثالًا للنحت ومثالًا للاقتـراض من معجم موثوق وفسر آلية التكوين.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"0ceee54c-088c-4480-8bbc-c8353244ff17","n":5,"title":"الاحتباس الحراري","passage":"يرتبط الاحتباس الحراري بتأثير الغازات الدفيئة في ميزانية الطاقة الأرضية، وتحتاج دراسة تغير المناخ إلى بيانات زمنية ومرجع علمي، لا الانطباع من يوم شديد الحرارة. نموذج أصلي يقارن طالب متوسطات طويلة الأمد بدل درجة حرارة يوم واحد.","question":"ما الدليل الأنسب لدراسة تغير المناخ؟","correct":"سلاسل قياس طويلة الأمد من مصادر موثوقة","wrong":["طقس يوم واحد","صورة بلا تاريخ","حكاية فردية"],"practice":"حلل مصدرًا علميًا موثقًا لبيانات مناخية وميز بين الطقس والمناخ.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"0ceee54c-088c-4480-8bbc-c8353244ff17","n":6,"title":"أثر التقنيات الحديثة على الحياة","passage":"تتغير آثار التقنية بحسب تصميم الأداة وإتاحة الوصول إليها والخصوصية وطريقة استخدامها، وقد تزيد الإنتاجية أو تخلق مشكلات جديدة. نموذج مستقل يختبر فريق تطبيقًا دراسيًا ويحدد زمن الاستخدام والمخاطر وطرق قياس الفائدة.","question":"ما الإجراء الضروري لتقويم أداة تقنية؟","correct":"تحديد منفعة ومخاطر ومقياس نتائج","wrong":["الاعتماد على الدعاية","إلغاء الخصوصية","افتراض النجاح دون تجربة"],"practice":"اكتب تقييمًا متوازنًا لأداة رقمية تعليمية يشمل الفوائد والقيود والدليل.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"},{"cid":"07545e67-c032-4bab-818d-d6e2fd9b5015","unit":"0ceee54c-088c-4480-8bbc-c8353244ff17","n":7,"title":"مهارة وضع خطة عمل","passage":"تشمل خطة العمل هدفًا محددًا وأنشطة ومسؤوليات وجدولًا زمنيًا وموارد ومؤشرات قياس ومراجعة للمخاطر. مثال أصلي يخطط طلاب لحملة قراءة شهرية ويحددون المسؤول عن الإعلان وعن متابعة المشاركة.","question":"ما الذي يمكن استخدامه لقياس تنفيذ الخطة؟","correct":"مؤشر أداء محدد قابل للتحقق","wrong":["شعار عام دون قياس","حذف المسؤوليات","مواعيد غير معلنة"],"practice":"ضع خطة من خمسة عناصر لنشاط مدرسي مع جدول ومؤشر ومخاطر محتملة.","old":"DADYOOM_MR_G12_SCIENTIFIC_OFFICIAL"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='MR' AND c.id=r.cid
    AND g.grade_number=12 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G12_SCIENCE_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G12_SCIENCE_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'MR_G12_SCIENCE_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G12_SCIENCE_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_MR_G12_SCIENCE_ORIGINAL_29_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G12_SCIENCE_ORIGINAL_29_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G12_SCIENCE_ORIGINAL_29_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_MR_G12_SCIENCE_ORIGINAL_29_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G12_SCIENCE_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;